import re

PHRASES = ['ignore previous instructions', 'ignore all previous', 'disregard the above', 'you are now', 'system prompt']

def looks_injected(text):
    return any(re.search(r'\s+'.join(map(re.escape, p.split())), text, re.I) for p in PHRASES)

